//! Offline capability AUTO-MINER bin (NL-BRIDGE-2-AUTO-MINER).
//!
//! Reflects the engine's synthesizable operator surface (string_synth `SExpr`,
//! array_transform `ReorderKind`) into a capability registry JSON in the same
//! schema as `coding_registry.json`, with example_cases AUTO-GENERATED by running
//! each op. Writes the COMMITTED `mined_capabilities.json` the NL bridge loads.
//!
//! Usage:
//!   mine_capabilities [--out <path>] [--check]
//!     (default out: ../../linguigenesis/data/mined_capabilities.json,
//!      relative to CARGO_MANIFEST_DIR — the same data dir the bridge reads)
//!   --check : do not write; exit non-zero if the on-disk file is stale
//!             (proves determinism in CI without mutating the tree).

use std::path::PathBuf;

fn default_out() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../linguigenesis/data/mined_capabilities.json")
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let check = args.iter().any(|a| a == "--check");
    let out = args
        .iter()
        .position(|a| a == "--out")
        .and_then(|i| args.get(i + 1))
        .map(PathBuf::from)
        .unwrap_or_else(default_out);

    let json = mog_synth::capability_miner::mine_capabilities_json();

    if check {
        match std::fs::read_to_string(&out) {
            Ok(existing) if existing == json => {
                println!("[mine_capabilities] {} is up to date", out.display());
            }
            Ok(_) => {
                eprintln!(
                    "[mine_capabilities] STALE: {} differs from freshly-mined output; re-run without --check",
                    out.display()
                );
                std::process::exit(1);
            }
            Err(e) => {
                eprintln!("[mine_capabilities] cannot read {}: {}", out.display(), e);
                std::process::exit(1);
            }
        }
        return;
    }

    if let Some(parent) = out.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    std::fs::write(&out, &json).unwrap_or_else(|e| {
        eprintln!("[mine_capabilities] write failed {}: {}", out.display(), e);
        std::process::exit(1);
    });
    let n = mog_synth::capability_miner::mined_lemmas().len();
    println!(
        "[mine_capabilities] wrote {} mined capabilities to {}",
        n,
        out.display()
    );
}
